<?php
namespace App\Http\Controllers;
use App\Models\AiAgentStep;use App\Models\EditorialPitch;use App\Models\EditorialSourceClaim;use App\Models\NewsArticle;use Illuminate\View\View;
class AdminEditorialRoomController extends Controller{public function __invoke():View{return view('admin.editorial-room.dashboard',['metrics'=>['active_pitches'=>EditorialPitch::whereNotIn('status',['published','discarded'])->count(),'overdue'=>EditorialPitch::whereNotNull('due_at')->where('due_at','<',now())->whereNotIn('status',['published','discarded'])->count(),'agent_reviews'=>AiAgentStep::where('status','pending_review')->count(),'fact_checks'=>EditorialSourceClaim::whereIn('status',['review_required','conflicting'])->count(),'editorial_reviews'=>NewsArticle::whereIn('workflow_status',['journalist_review','verification','editorial_review','changes_requested'])->count(),'scheduled'=>NewsArticle::where('workflow_status','scheduled')->count()],'latest'=>EditorialPitch::with('assignee')->latest('updated_at')->limit(8)->get()]);}}
